-- Self-check inside the transaction. If any count is short, this raises and the
-- whole batch rolls back rather than leaving a partial load behind.
do $$
declare p int; r int; qn int; i int; m int;
begin
  select count(*) into p from problems where problem_code ~ '^(FSH|FNB|GAM|HLT|TRV)-3[0-9][0-9]$';
  select count(*) into r from root_causes where root_cause_code ~ '^RC-(FSH|FNB|GAM|HLT|TRV)-3[0-9][0-9]-[0-9]$';
  select count(*) into qn from questions where question_code ~ '^S(0|01|10)-(FSH|FNB|GAM|HLT|TRV)-3[0-9][0-9]-[0-9]$';
  select count(*) into i from interventions where intervention_code ~ '^INT-(FSH|FNB|GAM|HLT|TRV)-3[0-9][0-9]-[0-9]$';
  select count(*) into m from question_industry_mapping qim join questions qq on qq.question_id=qim.question_id
    where qq.question_code ~ '^S(0|01|10)-(FSH|FNB|GAM|HLT|TRV)-3[0-9][0-9]-[0-9]$';
  if p <> 45 or r <> 135 or qn <> 270 or i <> 90 or m <> 270 then
    raise exception 'batch 3 incomplete: problems=% root_causes=% questions=% interventions=% mappings=% (expected 45/135/270/90/270)', p, r, qn, i, m;
  end if;
  raise notice 'batch 3 ok: 45 problems, 135 root causes, 270 questions, 90 interventions, 270 mappings';
end $$;

COMMIT;
