insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FSH-301', 'Great Eye for Clothes, No Feel for Stock', 'Founder Psychology', 'internal', 'The founder can design something people want to wear, but deciding how many of each size to make, and what to do with what does not sell, is a skill they have never had to learn. Money sits in unsold stock.', 5, 9, '["Designs well, buys stock badly", "Sizes run out or pile up", "Cash tied up in old stock", "Cannot say which style paid for itself"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["fashion_apparel"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-301-1', (select problem_id from problems where problem_code = 'FSH-301'), 'Buying Was Never Learned', 'Knowledge', 'Nobody taught the founder how to decide quantities per size and colour, so orders are placed on hope and past habit.', 0.76, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-301-2', (select problem_id from problems where problem_code = 'FSH-301'), 'Design Is the Comfortable Work', 'Psychological', 'Sketching and sampling feel like real progress, so the boring stock decisions keep getting pushed to the last minute.', 0.72, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-301-3', (select problem_id from problems where problem_code = 'FSH-301'), 'Old Stock Not Faced', 'Behavioural', 'Unsold pieces are not counted or marked down on a schedule, because doing so admits the buy was wrong.', 0.67, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-301-1', (select problem_id from problems where problem_code = 'FSH-301'), '["RC-FSH-301-1", "RC-FSH-301-2", "RC-FSH-301-3"]'::jsonb, 'Founder Leverage', 'Fashion & Apparel — Founder Skill Fit', '[]'::jsonb, '["Count what you still have from your last two drops, by size.", "Work out how much money is sitting in the sizes that never move.", "Cut those sizes from your next order and put the money into the ones that sold out."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["Your bestseller is not a style, it is a style in a size.", "Old stock is cash you already spent; count it before you buy again."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-301-2', (select problem_id from problems where problem_code = 'FSH-301'), '["RC-FSH-301-1", "RC-FSH-301-2", "RC-FSH-301-3"]'::jsonb, 'Founder Leverage', 'Fashion & Apparel — Founder Skill Fit', '[]'::jsonb, '["Write down the two things this business needs that you have never done.", "Ask someone who has bought stock for a living to check your next order before you place it.", "Sit with them while they do it, so you learn the reasoning."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["Name the gap before trying to close it.", "Borrow the skill once, learn it properly, then own it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into questions (question_code, category, question_text, problem_id, root_cause_id, question_type, difficulty_level, priority, is_distress_tagged, red_flag_pattern, green_flag_pattern, primary_stage_group, industry_relevance) values ('S0-FSH-301-1', 'Founder Psychology', 'Do you know which sizes sell out and which sit?', (select problem_id from problems where problem_code = 'FSH-301'), (select root_cause_id from root_causes where root_cause_code = 'RC-FSH-301-1'), 'open_text', 2, 'CORE', false, 'No', 'Yes, by size', 'Stage 0', '["fashion_apparel"]'::jsonb) on conflict (question_code) do nothing;
