insert into questions (question_code, category, question_text, problem_id, root_cause_id, question_type, difficulty_level, priority, is_distress_tagged, red_flag_pattern, green_flag_pattern, primary_stage_group, industry_relevance) values ('S10-FSH-301-2', 'Founder Psychology', 'What buying or numbers skill is still missing for you?', (select problem_id from problems where problem_code = 'FSH-301'), (select root_cause_id from root_causes where root_cause_code = 'RC-FSH-301-3'), 'open_text', 2, 'CORE', false, 'Cannot say', 'Named, with a plan', 'Stage 1→10+', '["fashion_apparel"]'::jsonb) on conflict (question_code) do nothing;
insert into question_industry_mapping (question_id, industry_code, stage_group, applicability_type) values ((select question_id from questions where question_code = 'S10-FSH-301-2'), 'fashion_apparel', 'Stage 1→10+', 'primary') on conflict (question_id, industry_code, stage_group) do nothing;
insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FSH-302', 'The Week Goes on Chasing the Tailor and the Courier', 'Founder Psychology', 'internal', 'Samples are late, a fabric arrives wrong, a delivery goes missing. The founder spends the week on the phone keeping today''s order moving, and never gets to the work that would stop next month''s order going the same way.', 5, 9, '["Week spent chasing suppliers", "Sample rounds keep slipping", "No time for planning the next drop", "The same supplier problems every season"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["fashion_apparel"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-302-1', (select problem_id from problems where problem_code = 'FSH-302'), 'Chasing Instead of Fixing', 'Behavioural', 'Each late sample is chased individually and nothing is changed about how suppliers are chosen or briefed, so it repeats.', 0.75, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-302-2', (select problem_id from problems where problem_code = 'FSH-302'), 'No Hours Reserved', 'Operational', 'No time is set aside for planning or supplier work, so only the emergency in front of the founder gets attention.', 0.71, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-302-3', (select problem_id from problems where problem_code = 'FSH-302'), 'Chasing Feels Productive', 'Psychological', 'A day of phone calls feels like hard work, which hides that the same calls will be needed next week.', 0.66, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-302-1', (select problem_id from problems where problem_code = 'FSH-302'), '["RC-FSH-302-1", "RC-FSH-302-2", "RC-FSH-302-3"]'::jsonb, 'Founder Leverage', 'Fashion & Apparel — Founder Time Use', '[]'::jsonb, '["Write down every supplier problem for one month and group them.", "Take the biggest group and change how you brief or choose for that step.", "Count that group again next month."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["A problem that repeats is a process gap, not bad luck.", "Count it before and after or you will not know if you fixed it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-302-2', (select problem_id from problems where problem_code = 'FSH-302'), '["RC-FSH-302-1", "RC-FSH-302-2", "RC-FSH-302-3"]'::jsonb, 'Founder Leverage', 'Fashion & Apparel — Founder Time Use', '[]'::jsonb, '["Write down where your hours went last week.", "Mark the ones only you could have done.", "Give one supplier relationship to someone else with the steps written down."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["Chasing is not a founder job once the steps exist."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
