insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FSH-303', 'Nothing Ships Without the Founder Seeing It', 'Founder Psychology', 'internal', 'Every sample, every photo, every price waits for the founder to look at it. The brand exists in their head as taste, never as written rules, so the whole business moves at the speed of one person''s attention.', 5, 9, '["Founder approves every sample", "Prices set one by one by the founder", "Photoshoots wait for the founder", "No written brand rules"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["fashion_apparel"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-303-1', (select problem_id from problems where problem_code = 'FSH-303'), 'Taste Never Written Down', 'Knowledge', 'The founder''s judgement about what is and is not the brand was never turned into rules anyone else could follow.', 0.77, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-303-2', (select problem_id from problems where problem_code = 'FSH-303'), 'Approval Is the Only Quality Check', 'Behavioural', 'Because approval is the only check, removing it feels like removing standards rather than replacing them with something.', 0.71, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-303-3', (select problem_id from problems where problem_code = 'FSH-303'), 'Fear of an Off-Brand Piece', 'Psychological', 'The founder fears one wrong product more than a slow season, so the bottleneck gets defended rather than fixed.', 0.66, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-303-1', (select problem_id from problems where problem_code = 'FSH-303'), '["RC-FSH-303-1", "RC-FSH-303-2", "RC-FSH-303-3"]'::jsonb, 'Founder Leverage', 'Fashion & Apparel — Founder Dependency', '[]'::jsonb, '["Write ten things your brand never does, with a picture for each.", "Write your pricing rule: what multiple of cost, and when you go lower.", "Let someone else approve one category against those rules for a season, then review what happened."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["Replace approval with written rules, not with hope.", "Review the season''s results, not each sample."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-303-2', (select problem_id from problems where problem_code = 'FSH-303'), '["RC-FSH-303-1", "RC-FSH-303-2", "RC-FSH-303-3"]'::jsonb, 'Founder Leverage', 'Fashion & Apparel — Founder Dependency', '[]'::jsonb, '["Name who owns product decisions and who owns pricing.", "Set the order value above which you must be asked.", "Review by what sold, not by what you saw before it shipped."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["Review outcomes, not items."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
