insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FSH-304', 'Everyone Does a Bit of Everything Each Drop', 'Team & Leadership', 'internal', 'The same three people handle design, stock, packing and social depending on who is free. Nobody owns a step, so when a drop goes wrong nobody can say where, and the fix lands on whoever notices.', 5, 9, '["Jobs assigned by who is free", "No owner per step", "Handover gaps between design and stock", "Nobody accountable when a drop slips"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["fashion_apparel"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-304-1', (select problem_id from problems where problem_code = 'FSH-304'), 'Roles Never Set', 'Behavioural', 'The team grew by adding hands rather than by defining jobs, so nobody has a step that is clearly theirs.', 0.75, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-304-2', (select problem_id from problems where problem_code = 'FSH-304'), 'Flexibility Treated as a Strength', 'Psychological', 'Everyone helping with everything feels like a good small team, which hides that no step has an owner.', 0.70, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-304-3', (select problem_id from problems where problem_code = 'FSH-304'), 'Handovers Unwritten', 'Operational', 'What has to be true before work passes from one person to the next was never agreed, so things fall between them.', 0.67, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-304-1', (select problem_id from problems where problem_code = 'FSH-304'), '["RC-FSH-304-1", "RC-FSH-304-2", "RC-FSH-304-3"]'::jsonb, 'Team Effectiveness', 'Fashion & Apparel — Role Clarity', '[]'::jsonb, '["List the steps a drop goes through, from sketch to dispatch.", "Write one name against each step.", "For each handover, write the one thing that must be finished before it passes on."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["One owner per step, even if the same person owns three.", "Most things go wrong at the handover, not inside the step."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-304-2', (select problem_id from problems where problem_code = 'FSH-304'), '["RC-FSH-304-1", "RC-FSH-304-2", "RC-FSH-304-3"]'::jsonb, 'Team Effectiveness', 'Fashion & Apparel — Role Clarity', '[]'::jsonb, '["Pick the step that slipped most last drop.", "Give it a single owner and tell the team who it is.", "Review that step alone after the next drop."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["Fix one handover properly rather than redrawing the whole team."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
