insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FSH-305', 'Discounts and Reorders Wait for the Founder', 'Team & Leadership', 'internal', 'Nobody else can mark something down, reorder a bestseller or accept a wholesale order. The rules exist only in the founder''s head, so the team asks about everything and stops asking about the small things that then go unmanaged.', 5, 9, '["All discounts need the founder", "Reorders wait for approval", "Wholesale terms decided one by one", "Team stops asking and things drift"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["fashion_apparel"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-305-1', (select problem_id from problems where problem_code = 'FSH-305'), 'Limits Never Written', 'Operational', 'No one has written down what the team may decide alone, so the safe choice is always to ask.', 0.76, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-305-2', (select problem_id from problems where problem_code = 'FSH-305'), 'Every Decision Feels Unique', 'Knowledge', 'Because past decisions were never turned into rules, each one is reasoned from scratch by the only person who remembers.', 0.71, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-305-3', (select problem_id from problems where problem_code = 'FSH-305'), 'Control Feels Like Care', 'Psychological', 'Approving each markdown feels like protecting the brand, so the founder does not notice how much it slows.', 0.66, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-305-1', (select problem_id from problems where problem_code = 'FSH-305'), '["RC-FSH-305-1", "RC-FSH-305-2", "RC-FSH-305-3"]'::jsonb, 'Team Effectiveness', 'Fashion & Apparel — Decision Rights', '[]'::jsonb, '["Write your discount rule: how deep, on what, after how long unsold.", "Write your reorder rule: at what stock level, up to what value.", "Let the team work inside both for one season and review the results, not the decisions."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["A written rule beats a fast approver.", "Review what the rules produced, not each use of them."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-305-2', (select problem_id from problems where problem_code = 'FSH-305'), '["RC-FSH-305-1", "RC-FSH-305-2", "RC-FSH-305-3"]'::jsonb, 'Team Effectiveness', 'Fashion & Apparel — Decision Rights', '[]'::jsonb, '["List the five decisions you get asked about most.", "For each, write who decides and up to what value.", "Put it where the team can see it."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["If it is asked five times it should be a rule, not a conversation."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
