insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FSH-306', 'Hiring Happens When a Drop Is Already Late', 'Team & Leadership', 'internal', 'People get hired in a panic mid-season, from whoever is available, with no written idea of the job. Some work out and nobody can say why, and the ones who do not are kept because replacing them would mean doing this again.', 5, 9, '["Hires made in a rush", "No written job description", "Cannot say why a good hire worked", "Weak hires kept too long"]'::jsonb, 5, 'Hiring Repeatability', 'hiring_repeatability', '["fashion_apparel"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-306-1', (select problem_id from problems where problem_code = 'FSH-306'), 'No Written Role', 'Operational', 'Hiring starts from a feeling of being short-handed rather than from a written job, so candidates are judged on likeability.', 0.75, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-306-2', (select problem_id from problems where problem_code = 'FSH-306'), 'Urgency Over Process', 'Behavioural', 'Because hiring only starts when it is already late, there is never time to do it properly.', 0.71, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-306-3', (select problem_id from problems where problem_code = 'FSH-306'), 'Nothing Learned Between Hires', 'Knowledge', 'What worked and what did not is never written down, so the fourth hire is made as blindly as the first.', 0.67, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-306-1', (select problem_id from problems where problem_code = 'FSH-306'), '["RC-FSH-306-1", "RC-FSH-306-2", "RC-FSH-306-3"]'::jsonb, 'Team Effectiveness', 'Fashion & Apparel — Hiring Repeatability', '[]'::jsonb, '["Write the job before you look: the five things this person must do in month one.", "Write how you will test each one in the interview.", "Give every candidate the same test and write down what you saw."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["Test the work, not the conversation.", "The same test across candidates is what makes a comparison possible."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-306-2', (select problem_id from problems where problem_code = 'FSH-306'), '["RC-FSH-306-1", "RC-FSH-306-2", "RC-FSH-306-3"]'::jsonb, 'Team Effectiveness', 'Fashion & Apparel — Hiring Repeatability', '[]'::jsonb, '["Look back at your last three hires: who worked out and what did you see early?", "Turn that into two things you check every time.", "Start looking one drop before you need the person."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["Hire from a written role, not from a shortage."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
