insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FSH-307', 'The Brand Story and the Next Drop Point Different Ways', 'Strategy & Planning', 'internal', 'The founder talks about a considered, long-lasting label, and then the calendar is full of fast trend pieces because they move. Each drop is defensible on its own and the set of them is building something else.', 5, 9, '["Stated brand and actual drops differ", "Trend pieces crowd out core styles", "Cannot say what the label stands for in products", "Direction changes by season"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["fashion_apparel"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-307-1', (select problem_id from problems where problem_code = 'FSH-307'), 'Plan Never Checked Against the Story', 'Strategic', 'There is no moment where the next season is held up against what the brand claims to be, so drift is never seen.', 0.76, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-307-2', (select problem_id from problems where problem_code = 'FSH-307'), 'Fast Sellers Set the Direction', 'Behavioural', 'Whatever sold quickly last month decides what gets made next, so the brand is steered by its own noise.', 0.72, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-307-3', (select problem_id from problems where problem_code = 'FSH-307'), 'Story Too Vague to Test Against', 'Knowledge', 'The brand is described in feelings rather than in rules about product, so nothing can be judged against it.', 0.67, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-307-1', (select problem_id from problems where problem_code = 'FSH-307'), '["RC-FSH-307-1", "RC-FSH-307-2", "RC-FSH-307-3"]'::jsonb, 'Strategic Focus', 'Fashion & Apparel — Plan and Vision', '[]'::jsonb, '["Write what your label is in three product rules, not adjectives.", "Hold your next drop against those three rules, piece by piece.", "Cut or keep each piece on that basis and write down why."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["A brand you cannot test a product against is a mood, not a brand.", "Write the reason down so next season can read it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-307-2', (select problem_id from problems where problem_code = 'FSH-307'), '["RC-FSH-307-1", "RC-FSH-307-2", "RC-FSH-307-3"]'::jsonb, 'Strategic Focus', 'Fashion & Apparel — Plan and Vision', '[]'::jsonb, '["List what you made last year and mark each piece core or trend.", "Work out what share was trend.", "Decide the share you actually want and plan the next drop to it."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["Decide the mix on purpose rather than discovering it afterwards."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
