insert into question_industry_mapping (question_id, industry_code, stage_group, applicability_type) values ((select question_id from questions where question_code = 'S10-FSH-307-2'), 'fashion_apparel', 'Stage 1→10+', 'primary') on conflict (question_id, industry_code, stage_group) do nothing;
insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FSH-308', 'Everything Is Urgent Because the Season Already Started', 'Strategy & Planning', 'internal', 'The list has new styles, a website fix, three collaborations and a stockroom nobody can find anything in. All of it is started, none of it finishes, and the thing that would actually move the season is somewhere in the middle.', 5, 9, '["Too much started at once", "Nothing finishes", "No ranking on the list", "The important work stalls behind the loud work"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["fashion_apparel"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-308-1', (select problem_id from problems where problem_code = 'FSH-308'), 'Nothing Ranked', 'Strategic', 'The list is a list, not an order, so effort spreads evenly across things of very different value.', 0.75, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-308-2', (select problem_id from problems where problem_code = 'FSH-308'), 'Saying No Feels Like Losing', 'Psychological', 'Turning down a collaboration or an idea feels like missed opportunity, so everything stays on the list.', 0.71, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-308-3', (select problem_id from problems where problem_code = 'FSH-308'), 'Loudest Wins', 'Behavioural', 'Whatever someone chased hardest this week gets the attention, regardless of what it is worth.', 0.67, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-308-1', (select problem_id from problems where problem_code = 'FSH-308'), '["RC-FSH-308-1", "RC-FSH-308-2", "RC-FSH-308-3"]'::jsonb, 'Strategic Focus', 'Fashion & Apparel — Prioritisation', '[]'::jsonb, '["Write everything you are working on in one list.", "Pick the one thing that would most change this season and say so out loud.", "Stop two others this week and tell the team they are stopped."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["Stopping things is the decision; starting them was not.", "Say what is stopped or the team will keep working on it quietly."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-308-2', (select problem_id from problems where problem_code = 'FSH-308'), '["RC-FSH-308-1", "RC-FSH-308-2", "RC-FSH-308-3"]'::jsonb, 'Strategic Focus', 'Fashion & Apparel — Prioritisation', '[]'::jsonb, '["Write the rule you will use to rank: what does this do for the season?", "Rank the list with it.", "Work the top two only until they are done."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["A written rule survives a loud week better than a good intention."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
