insert into question_industry_mapping (question_id, industry_code, stage_group, applicability_type) values ((select question_id from questions where question_code = 'S10-FSH-308-2'), 'fashion_apparel', 'Stage 1→10+', 'primary') on conflict (question_id, industry_code, stage_group) do nothing;
insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FSH-309', 'Every Season Starts From Nothing', 'Strategy & Planning', 'internal', 'Which fabric shrank, which factory missed a deadline, which size curve was wrong — all of it lived in someone''s memory, and the ones who remember have moved on. So each season repeats mistakes it already paid for.', 5, 9, '["Supplier history not written down", "Same fabric problems repeat", "Size mistakes repeated", "Knowledge leaves with people"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["fashion_apparel"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-309-1', (select problem_id from problems where problem_code = 'FSH-309'), 'Nothing Written Down', 'Operational', 'Supplier results, fabric behaviour and size outcomes were never recorded, so the business cannot learn from its own seasons.', 0.77, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-309-2', (select problem_id from problems where problem_code = 'FSH-309'), 'Memory Held by People', 'Knowledge', 'What the business knows lives in a few heads, so it walks out when they do.', 0.72, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FSH-309-3', (select problem_id from problems where problem_code = 'FSH-309'), 'Looking Back Feels Like Blame', 'Psychological', 'Reviewing a season honestly feels like finding fault, so it is skipped and the lesson is lost.', 0.66, 'internal', 'Stage 0→1', '["fashion_apparel"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FSH-309-1', (select problem_id from problems where problem_code = 'FSH-309'), '["RC-FSH-309-1", "RC-FSH-309-2", "RC-FSH-309-3"]'::jsonb, 'Strategic Focus', 'Fashion & Apparel — What Gets Remembered', '[]'::jsonb, '["Start one page per supplier: what they made, what went wrong, what it cost.", "Fill it in the week something happens, not at season end.", "Read the pages before you place the next order."]'::jsonb, '[3, 4, 5]'::jsonb, '["fashion_apparel"]'::jsonb, '["Write it when it happens or it will not be written.", "The point of the record is the reading, not the writing."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
