insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FNB-301', 'Cooks Beautifully, Cannot Say What a Plate Costs', 'Founder Psychology', 'internal', 'The food is genuinely good and people come back for it. What one dish costs to put on a table, once waste and staff time are counted, has never been worked out — so prices are set by looking at the place down the road.', 5, 9, '["Great food, unknown costs", "Prices copied from nearby places", "Waste not counted", "Cannot say which dish makes money"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["foodtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-301-1', (select problem_id from problems where problem_code = 'FNB-301'), 'Costing Never Learned', 'Knowledge', 'Nobody taught the founder how to cost a dish including waste and labour, so the menu is priced by comparison instead.', 0.77, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-301-2', (select problem_id from problems where problem_code = 'FNB-301'), 'The Kitchen Is the Comfortable Place', 'Psychological', 'Cooking and menu work feel like the real job, so the costing keeps being left for a quieter week that never comes.', 0.72, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-301-3', (select problem_id from problems where problem_code = 'FNB-301'), 'Waste Treated as Normal', 'Behavioural', 'Thrown-away food is accepted as part of the trade rather than measured, so its true size is never seen.', 0.67, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FNB-301-1', (select problem_id from problems where problem_code = 'FNB-301'), '["RC-FNB-301-1", "RC-FNB-301-2", "RC-FNB-301-3"]'::jsonb, 'Founder Leverage', 'Food & Beverage / FoodTech — Founder Skill Fit', '[]'::jsonb, '["Cost one dish properly: ingredients, the bit thrown away, and the time to make it.", "Compare that to what you charge for it.", "Do the same for your five best-selling dishes before touching the rest of the menu."]'::jsonb, '[3, 4, 5]'::jsonb, '["foodtech"]'::jsonb, '["A dish that sells well and loses money is your biggest problem, not your best seller.", "Five dishes done properly beats a whole menu done roughly."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FNB-301-2', (select problem_id from problems where problem_code = 'FNB-301'), '["RC-FNB-301-1", "RC-FNB-301-2", "RC-FNB-301-3"]'::jsonb, 'Founder Leverage', 'Food & Beverage / FoodTech — Founder Skill Fit', '[]'::jsonb, '["Weigh what gets thrown away for one week, by item.", "Work out what that week cost you.", "Change the order quantity or the prep for the worst item and weigh again."]'::jsonb, '[3, 4, 5]'::jsonb, '["foodtech"]'::jsonb, '["Waste is cash; weigh it before arguing about it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
