insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FNB-302', 'The Founder Is On the Floor Every Service', 'Founder Psychology', 'internal', 'Someone does not turn up, a delivery is short, a customer complains. The founder is in it every day, every service, and the work of making next month easier never starts because there is no hour left in which to start it.', 5, 9, '["Founder works every service", "Days spent covering absences", "No time for planning", "The same crises every week"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["foodtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-302-1', (select problem_id from problems where problem_code = 'FNB-302'), 'Covering Instead of Fixing', 'Behavioural', 'Each gap is filled by the founder personally, so the reason the gap keeps appearing is never worked on.', 0.76, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-302-2', (select problem_id from problems where problem_code = 'FNB-302'), 'No Hours Set Aside', 'Operational', 'No time is protected for planning or training, so only today''s service gets attention.', 0.71, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-302-3', (select problem_id from problems where problem_code = 'FNB-302'), 'Being There Feels Like Standards', 'Psychological', 'The founder believes quality depends on their presence, which makes stepping back feel like letting standards slip.', 0.68, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FNB-302-1', (select problem_id from problems where problem_code = 'FNB-302'), '["RC-FNB-302-1", "RC-FNB-302-2", "RC-FNB-302-3"]'::jsonb, 'Founder Leverage', 'Food & Beverage / FoodTech — Founder Time Use', '[]'::jsonb, '["Write down every time you had to step in for one month, and why.", "Group them and pick the biggest group.", "Spend one protected day fixing that cause — a rota rule, a trained second person, a written prep list."]'::jsonb, '[3, 4, 5]'::jsonb, '["foodtech"]'::jsonb, '["If you are the backup for everything, you are the plan.", "Count the times before and after or you will not know it worked."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FNB-302-2', (select problem_id from problems where problem_code = 'FNB-302'), '["RC-FNB-302-1", "RC-FNB-302-2", "RC-FNB-302-3"]'::jsonb, 'Founder Leverage', 'Food & Beverage / FoodTech — Founder Time Use', '[]'::jsonb, '["Write down where your hours went last week.", "Mark the ones only you could have done.", "Train one person to cover one shift type completely."]'::jsonb, '[3, 4, 5]'::jsonb, '["foodtech"]'::jsonb, '["One person trained properly beats being present yourself."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
