insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FNB-303', 'The Recipes and the Suppliers Live in the Founder''s Head', 'Founder Psychology', 'internal', 'Quantities are by feel, the supplier relationships are personal, and the menu changes when the founder decides it does. Nothing is written, so nothing can happen without them and the business cannot be in two places.', 5, 9, '["Recipes not written down", "Supplier relationships personal to the founder", "Menu changes only when the founder says", "Cannot open a second place"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["foodtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-303-1', (select problem_id from problems where problem_code = 'FNB-303'), 'Recipes Never Written', 'Knowledge', 'Quantities and method live in the founder''s hands, so consistency depends on them being there.', 0.78, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-303-2', (select problem_id from problems where problem_code = 'FNB-303'), 'Relationships Not Transferred', 'Operational', 'Suppliers deal with the founder personally and nobody else has the contacts or the terms.', 0.72, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-303-3', (select problem_id from problems where problem_code = 'FNB-303'), 'Written Recipes Feel Like Giving It Away', 'Psychological', 'Writing the method down feels like handing over what makes the food special, so it does not get done.', 0.66, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FNB-303-1', (select problem_id from problems where problem_code = 'FNB-303'), '["RC-FNB-303-1", "RC-FNB-303-2", "RC-FNB-303-3"]'::jsonb, 'Founder Leverage', 'Food & Beverage / FoodTech — Founder Dependency', '[]'::jsonb, '["Write your ten best-selling dishes as recipes with real quantities.", "Have someone else cook three of them from the page while you watch and say nothing.", "Fix what the page got wrong, not what the cook got wrong."]'::jsonb, '[3, 4, 5]'::jsonb, '["foodtech"]'::jsonb, '["If someone cannot cook it from the page, the page is wrong.", "Watching silently is the only honest test."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FNB-303-2', (select problem_id from problems where problem_code = 'FNB-303'), '["RC-FNB-303-1", "RC-FNB-303-2", "RC-FNB-303-3"]'::jsonb, 'Founder Leverage', 'Food & Beverage / FoodTech — Founder Dependency', '[]'::jsonb, '["List your suppliers, what you pay and who else could call them.", "Introduce one other person to your two biggest suppliers.", "Let them place the next order while you check it afterwards."]'::jsonb, '[3, 4, 5]'::jsonb, '["foodtech"]'::jsonb, '["A relationship only one person holds is a risk, not an asset."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into questions (question_code, category, question_text, problem_id, root_cause_id, question_type, difficulty_level, priority, is_distress_tagged, red_flag_pattern, green_flag_pattern, primary_stage_group, industry_relevance) values ('S0-FNB-303-1', 'Founder Psychology', 'Are your recipes written down with quantities?', (select problem_id from problems where problem_code = 'FNB-303'), (select root_cause_id from root_causes where root_cause_code = 'RC-FNB-303-1'), 'open_text', 2, 'CORE', false, 'No, they are in your head', 'Written with quantities', 'Stage 0', '["foodtech"]'::jsonb) on conflict (question_code) do nothing;
