insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FNB-304', 'The Rota Decides Who Does What', 'Team & Leadership', 'internal', 'Prep, ordering, cleaning and cash all land on whoever is on shift. Nobody owns any of them, so standards move with the rota and when something is wrong there is no one to ask about it.', 5, 9, '["Jobs follow the rota, not people", "No owner for ordering or prep", "Standards vary by shift", "Nobody accountable for a recurring miss"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["foodtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-304-1', (select problem_id from problems where problem_code = 'FNB-304'), 'Roles Never Set', 'Behavioural', 'The team was built as shifts to cover rather than jobs to own, so no task has a permanent owner.', 0.76, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-304-2', (select problem_id from problems where problem_code = 'FNB-304'), 'Everyone Helps With Everything', 'Psychological', 'A team where anyone does anything feels willing and close-knit, which hides that nothing is owned.', 0.70, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-304-3', (select problem_id from problems where problem_code = 'FNB-304'), 'Handovers Unwritten', 'Operational', 'What must be true at the end of one shift for the next to start clean was never agreed.', 0.67, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FNB-304-1', (select problem_id from problems where problem_code = 'FNB-304'), '["RC-FNB-304-1", "RC-FNB-304-2", "RC-FNB-304-3"]'::jsonb, 'Team Effectiveness', 'Food & Beverage / FoodTech — Role Clarity', '[]'::jsonb, '["List the jobs that must happen whoever is on: ordering, prep, close, cash.", "Put one name against each, not one shift.", "Write what must be done at handover and stick it where the shift changes."]'::jsonb, '[3, 4, 5]'::jsonb, '["foodtech"]'::jsonb, '["Own the job, not the shift.", "Most misses happen at the shift change, not during the shift."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FNB-304-2', (select problem_id from problems where problem_code = 'FNB-304'), '["RC-FNB-304-1", "RC-FNB-304-2", "RC-FNB-304-3"]'::jsonb, 'Team Effectiveness', 'Food & Beverage / FoodTech — Role Clarity', '[]'::jsonb, '["Pick the job that gets missed most.", "Give it one owner and tell everyone who that is.", "Check that job alone for two weeks."]'::jsonb, '[3, 4, 5]'::jsonb, '["foodtech"]'::jsonb, '["Fix one owner properly before redrawing the whole team."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
