insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FNB-305', 'Nobody Can Spend, Comp or Reorder Without Asking', 'Team & Leadership', 'internal', 'A manager cannot take a dish off a bill, order extra stock or send something back without the founder. So problems wait, customers wait, and the founder''s phone is the bottleneck for a fifty-rupee decision.', 5, 9, '["Every comp needs the founder", "Stock orders wait for approval", "No spending limit for managers", "Problems wait for a phone call"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["foodtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-305-1', (select problem_id from problems where problem_code = 'FNB-305'), 'Limits Never Written', 'Operational', 'No amount has been written down that a manager may spend or waive alone, so the safe answer is always to ask.', 0.77, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-305-2', (select problem_id from problems where problem_code = 'FNB-305'), 'Judgement Not Trusted Yet', 'Psychological', 'The founder has not seen the team decide, so does not trust them to — and never will while nobody is allowed to.', 0.71, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-305-3', (select problem_id from problems where problem_code = 'FNB-305'), 'Past Decisions Not Turned Into Rules', 'Knowledge', 'The same situations have been decided many times and never written up, so each one is reasoned again.', 0.66, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FNB-305-1', (select problem_id from problems where problem_code = 'FNB-305'), '["RC-FNB-305-1", "RC-FNB-305-2", "RC-FNB-305-3"]'::jsonb, 'Team Effectiveness', 'Food & Beverage / FoodTech — Decision Rights', '[]'::jsonb, '["Write the comp rule: what a manager may take off a bill, and up to what amount.", "Write the stock rule: what may be reordered without asking, up to what value.", "Let managers use both for a month, then review the totals rather than each case."]'::jsonb, '[3, 4, 5]'::jsonb, '["foodtech"]'::jsonb, '["A written limit beats a fast phone.", "Review what the limits cost you in total, not case by case."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FNB-305-2', (select problem_id from problems where problem_code = 'FNB-305'), '["RC-FNB-305-1", "RC-FNB-305-2", "RC-FNB-305-3"]'::jsonb, 'Team Effectiveness', 'Food & Beverage / FoodTech — Decision Rights', '[]'::jsonb, '["List the five things you get called about most.", "For each, write who decides and up to what value.", "Put it on the wall where the shift starts."]'::jsonb, '[3, 4, 5]'::jsonb, '["foodtech"]'::jsonb, '["Five calls a week is a missing rule, not a busy phone."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
