insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FNB-306', 'Hiring Starts the Day Someone Walks Out', 'Team & Leadership', 'internal', 'Kitchen and floor hiring happens under pressure, from whoever is around, with nothing written about the job. Turnover is high, which causes more rushed hiring, which causes more turnover.', 5, 9, '["Hiring only when short-staffed", "No written job description", "High turnover", "Cannot say why a good hire stayed"]'::jsonb, 5, 'Hiring Repeatability', 'hiring_repeatability', '["foodtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-306-1', (select problem_id from problems where problem_code = 'FNB-306'), 'No Written Role', 'Operational', 'Hiring begins from a gap in the rota rather than a written job, so anyone available looks suitable.', 0.76, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-306-2', (select problem_id from problems where problem_code = 'FNB-306'), 'Urgency Over Process', 'Behavioural', 'Because it always starts late, there is never time to test the work or check a reference.', 0.72, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-306-3', (select problem_id from problems where problem_code = 'FNB-306'), 'Nothing Learned Between Hires', 'Knowledge', 'Why people stayed or left is never written down, so the pattern that causes turnover is never seen.', 0.68, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FNB-306-1', (select problem_id from problems where problem_code = 'FNB-306'), '["RC-FNB-306-1", "RC-FNB-306-2", "RC-FNB-306-3"]'::jsonb, 'Team Effectiveness', 'Food & Beverage / FoodTech — Hiring Repeatability', '[]'::jsonb, '["Write the job first: the five things this person must do in week one.", "Add a paid trial shift and write down what you watched for.", "Use the same trial and the same notes for every candidate."]'::jsonb, '[3, 4, 5]'::jsonb, '["foodtech"]'::jsonb, '["A trial shift tells you more than any interview.", "The same notes across people are what let you compare them."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FNB-306-2', (select problem_id from problems where problem_code = 'FNB-306'), '["RC-FNB-306-1", "RC-FNB-306-2", "RC-FNB-306-3"]'::jsonb, 'Team Effectiveness', 'Food & Beverage / FoodTech — Hiring Repeatability', '[]'::jsonb, '["Write down why your last five leavers left.", "Fix the reason that appears most before hiring again.", "Start looking a month before you expect to be short."]'::jsonb, '[3, 4, 5]'::jsonb, '["foodtech"]'::jsonb, '["Turnover is a reason, not a fact of the trade."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
