insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FNB-307', 'One Good Place, and a Plan Built for Ten', 'Strategy & Planning', 'internal', 'The founder talks about a chain, and every decision is made for this one kitchen: recipes by feel, staff trained by watching, suppliers chosen by convenience. Nothing being built now would survive being copied.', 5, 9, '["Talks chain, builds one-off", "Nothing written to copy from", "Training by watching only", "Suppliers chosen for this location only"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["foodtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-307-1', (select problem_id from problems where problem_code = 'FNB-307'), 'Plan Never Checked Against the Goal', 'Strategic', 'Nobody asks whether today''s way of working could be copied, so the gap grows quietly.', 0.77, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-307-2', (select problem_id from problems where problem_code = 'FNB-307'), 'Today''s Service Decides Everything', 'Behavioural', 'Every choice is made for tonight, and tonight never asks whether it can be repeated elsewhere.', 0.72, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-307-3', (select problem_id from problems where problem_code = 'FNB-307'), 'Goal Too Vague to Test', 'Knowledge', 'The ambition is a number of outlets rather than a description of what must be true to open one.', 0.66, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FNB-307-1', (select problem_id from problems where problem_code = 'FNB-307'), '["RC-FNB-307-1", "RC-FNB-307-2", "RC-FNB-307-3"]'::jsonb, 'Strategic Focus', 'Food & Beverage / FoodTech — Plan and Vision', '[]'::jsonb, '["Write what must exist before you could open a second place: recipes, training, suppliers, numbers.", "Mark which of those exist today.", "Build the missing one that would take longest, starting now."]'::jsonb, '[3, 4, 5]'::jsonb, '["foodtech"]'::jsonb, '["A second place needs written things, not more effort.", "Start with the slowest missing piece, not the easiest."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
