insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FNB-308', 'A New Menu, a Second Outlet and Delivery, All This Quarter', 'Strategy & Planning', 'internal', 'Three big pushes are running at once and all three are half-finished. Each was a good idea on the day it started, and together they are a kitchen that does nothing especially well.', 5, 9, '["Several big pushes at once", "All half-finished", "No ranking", "Core offer neglected while new things start"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["foodtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-308-1', (select problem_id from problems where problem_code = 'FNB-308'), 'Nothing Ranked', 'Strategic', 'Ideas are added to the list and never placed in an order, so attention spreads across things of unequal value.', 0.76, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-308-2', (select problem_id from problems where problem_code = 'FNB-308'), 'Opportunity Feels Like Obligation', 'Psychological', 'Each new channel feels like something that must be taken, so nothing gets refused.', 0.71, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-308-3', (select problem_id from problems where problem_code = 'FNB-308'), 'Newest Idea Wins', 'Behavioural', 'Attention follows whatever was most recently discussed rather than what matters most.', 0.67, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
