insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('FNB-309', 'Every Cook Learns the Same Lessons Again', 'Strategy & Planning', 'internal', 'Which supplier sends bad stock in the rains, which dish falls apart on a delivery, what last year''s festival week actually needed — all of it is in the heads of people who may not be here next year.', 5, 9, '["Nothing written about suppliers", "Same problems each season", "Festival planning from memory", "Knowledge leaves with staff"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["foodtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-309-1', (select problem_id from problems where problem_code = 'FNB-309'), 'Nothing Written Down', 'Operational', 'Supplier performance, seasonal demand and dish problems were never recorded, so the business relearns them each year.', 0.78, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-309-2', (select problem_id from problems where problem_code = 'FNB-309'), 'Memory Held by People', 'Knowledge', 'What the kitchen knows lives in a few heads, and turnover in this trade is high.', 0.73, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-FNB-309-3', (select problem_id from problems where problem_code = 'FNB-309'), 'Reviewing Feels Like Blame', 'Psychological', 'Going back over a bad week feels like finding fault with the team, so it is skipped.', 0.66, 'internal', 'Stage 0→1', '["foodtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FNB-309-1', (select problem_id from problems where problem_code = 'FNB-309'), '["RC-FNB-309-1", "RC-FNB-309-2", "RC-FNB-309-3"]'::jsonb, 'Strategic Focus', 'Food & Beverage / FoodTech — What Gets Remembered', '[]'::jsonb, '["Start one page per supplier: what arrived, what was wrong, what it cost.", "Fill it in the week it happens.", "Read the pages before the next season''s ordering."]'::jsonb, '[3, 4, 5]'::jsonb, '["foodtech"]'::jsonb, '["Write it when it happens or it will not be written.", "The record is worth nothing unless it gets read before a decision."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-FNB-309-2', (select problem_id from problems where problem_code = 'FNB-309'), '["RC-FNB-309-1", "RC-FNB-309-2", "RC-FNB-309-3"]'::jsonb, 'Strategic Focus', 'Food & Beverage / FoodTech — What Gets Remembered', '[]'::jsonb, '["After this festival or busy period, write three things that went wrong and why.", "Turn each into an instruction for next time.", "Read it a month before the next one."]'::jsonb, '[3, 4, 5]'::jsonb, '["foodtech"]'::jsonb, '["A lesson without an instruction attached is just a story."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
