insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('GAM-301', 'Builds the Game Well, Cannot Read the Players', 'Founder Psychology', 'internal', 'The founder can design and ship something genuinely fun. Whether players come back on day seven, what a paying player is worth, and where people stop playing are things they have never learned to read, so the game is improved on instinct.', 5, 9, '["Strong at building, weak at player numbers", "Does not know day-7 return rate", "Changes made on instinct", "Cannot say what a paying player is worth"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["gaming"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-301-1', (select problem_id from problems where problem_code = 'GAM-301'), 'Player Numbers Never Learned', 'Knowledge', 'Nobody taught the founder which few numbers tell you whether a game is working, so the data sits unread.', 0.76, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-301-2', (select problem_id from problems where problem_code = 'GAM-301'), 'Building Is the Comfortable Work', 'Psychological', 'Making the next feature feels like progress, while reading what the last one did feels like admin.', 0.72, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-301-3', (select problem_id from problems where problem_code = 'GAM-301'), 'Instinct Has Worked So Far', 'Behavioural', 'Early decisions made on feel turned out fine, which has taught the founder that feel is enough.', 0.67, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-301-1', (select problem_id from problems where problem_code = 'GAM-301'), '["RC-GAM-301-1", "RC-GAM-301-2", "RC-GAM-301-3"]'::jsonb, 'Founder Leverage', 'Gaming — Founder Skill Fit', '[]'::jsonb, '["Pick three numbers only: how many come back the next day, how many on day seven, and where they stop playing.", "Look at them for your current build before changing anything.", "Make one change aimed at one of the three, and look again a week later."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["Three numbers you check beat twenty you do not.", "One change at a time, or you will not know what did it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-301-2', (select problem_id from problems where problem_code = 'GAM-301'), '["RC-GAM-301-1", "RC-GAM-301-2", "RC-GAM-301-3"]'::jsonb, 'Founder Leverage', 'Gaming — Founder Skill Fit', '[]'::jsonb, '["Write the two things this business needs that you have never done.", "Take the bigger one to someone who has run a live game.", "Do it yourself for a month before handing it to anyone."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["Name the gap before trying to close it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
