insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('GAM-302', 'The Founder Is Still the Best Developer, So They Code All Week', 'Founder Psychology', 'internal', 'Bugs, builds and store submissions take the founder''s week because they are fastest at them. The work that only a founder can do — deciding what the game is for, choosing what not to build — has no hours left.', 5, 9, '["Founder codes full time", "Builds and submissions handled personally", "No hours for direction", "Same firefighting each release"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["gaming"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-302-1', (select problem_id from problems where problem_code = 'GAM-302'), 'Fastest Person Does the Work', 'Behavioural', 'The founder is quickest at the technical work, so it keeps landing on them and never gets handed over.', 0.75, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-302-2', (select problem_id from problems where problem_code = 'GAM-302'), 'No Hours Reserved', 'Operational', 'No time is protected for direction or for reading player data, so only the build gets attention.', 0.71, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-302-3', (select problem_id from problems where problem_code = 'GAM-302'), 'Coding Is the Safe Place', 'Psychological', 'Shipping code has a clear finish line; deciding direction does not, so the code wins the day.', 0.68, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-302-1', (select problem_id from problems where problem_code = 'GAM-302'), '["RC-GAM-302-1", "RC-GAM-302-2", "RC-GAM-302-3"]'::jsonb, 'Founder Leverage', 'Gaming — Founder Time Use', '[]'::jsonb, '["Write down where your hours went last week.", "Mark the hours only a founder could have spent.", "Protect one full day a week for those and hold it."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["Being the fastest at a task is the reason to hand it over, not to keep it.", "A protected day survives; a good intention does not."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
