insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('GAM-303', 'Every Design Call Comes Back to the Founder''s Taste', 'Founder Psychology', 'internal', 'What is fun, what is fair, what goes in the next update — all of it is decided by one person''s judgement, and that judgement has never been written down as rules anyone else could apply.', 5, 9, '["Founder decides every design call", "Design rules unwritten", "Team waits for the founder''s opinion", "Updates stall when the founder is busy"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["gaming"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-303-1', (select problem_id from problems where problem_code = 'GAM-303'), 'Taste Never Written as Rules', 'Knowledge', 'The founder''s sense of what the game should be was never turned into principles, so it cannot be applied by anyone else.', 0.77, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-303-2', (select problem_id from problems where problem_code = 'GAM-303'), 'Opinion Used as Quality Control', 'Behavioural', 'The founder''s review is the only check on design, so removing it feels like removing quality.', 0.72, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-303-3', (select problem_id from problems where problem_code = 'GAM-303'), 'Fear of a Ruined Game', 'Psychological', 'The founder fears one bad design decision more than months of slow iteration, so the bottleneck is defended.', 0.67, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-303-1', (select problem_id from problems where problem_code = 'GAM-303'), '["RC-GAM-303-1", "RC-GAM-303-2", "RC-GAM-303-3"]'::jsonb, 'Founder Leverage', 'Gaming — Founder Dependency', '[]'::jsonb, '["Write ten design rules your game follows, with an example of each in the build.", "Write what your game never does.", "Let a designer ship one feature against those rules and review what players did with it."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["Write the rules, not the verdicts.", "Review what players did, not what the feature looked like."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-303-2', (select problem_id from problems where problem_code = 'GAM-303'), '["RC-GAM-303-1", "RC-GAM-303-2", "RC-GAM-303-3"]'::jsonb, 'Founder Leverage', 'Gaming — Founder Dependency', '[]'::jsonb, '["Name who owns game design and who owns monetisation.", "Set the size of change above which you are consulted.", "Review by player numbers, not by build review."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["Review outcomes, not features."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
