insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('GAM-304', 'Everyone Is a Generalist and the Live Game Suffers', 'Team & Leadership', 'internal', 'The same few people do art, code, community and store updates depending on the week. It worked while building; now the game is live and nobody owns keeping it healthy, so live problems get whoever is free.', 5, 9, '["Jobs assigned by availability", "Nobody owns the live game", "Community handled by whoever notices", "Gaps between build and live work"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["gaming"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-304-1', (select problem_id from problems where problem_code = 'GAM-304'), 'Roles Never Set for Live', 'Behavioural', 'The team was organised to ship a game, not to run one, so live responsibilities have no owner.', 0.76, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-304-2', (select problem_id from problems where problem_code = 'GAM-304'), 'Generalist Culture Prized', 'Psychological', 'Everyone doing everything feels like a strong small studio, which hides that live work has no home.', 0.70, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-304-3', (select problem_id from problems where problem_code = 'GAM-304'), 'Handovers Unwritten', 'Operational', 'What must be true before a build goes live was never agreed, so problems appear after launch.', 0.68, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-304-1', (select problem_id from problems where problem_code = 'GAM-304'), '["RC-GAM-304-1", "RC-GAM-304-2", "RC-GAM-304-3"]'::jsonb, 'Team Effectiveness', 'Gaming — Role Clarity', '[]'::jsonb, '["List what has to happen every week now the game is live.", "Put one name against each.", "Write the checklist that must be finished before a build goes to players."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["A live game is a job, not an afterthought.", "The checklist is the handover; without it the handover does not exist."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-304-2', (select problem_id from problems where problem_code = 'GAM-304'), '["RC-GAM-304-1", "RC-GAM-304-2", "RC-GAM-304-3"]'::jsonb, 'Team Effectiveness', 'Gaming — Role Clarity', '[]'::jsonb, '["Pick what went wrong most in the last two releases.", "Give that one thing a single owner and tell the team.", "Review that one thing after the next release."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["One owner properly assigned beats a new team structure."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
