insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('GAM-305', 'Nobody Can Change a Price or a Drop Rate Alone', 'Team & Leadership', 'internal', 'Every economy tweak, price change and event decision goes through the founder. Live games need small changes quickly, and this one gets them slowly, so the numbers that would improve stay unchanged.', 5, 9, '["All economy changes need the founder", "Event decisions wait", "No written limits on tuning", "Small improvements never happen"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["gaming"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-305-1', (select problem_id from problems where problem_code = 'GAM-305'), 'Limits Never Written', 'Knowledge', 'Nobody wrote down what may be tuned without asking, so everything is asked about.', 0.77, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-305-2', (select problem_id from problems where problem_code = 'GAM-305'), 'Economy Feels Too Delicate to Delegate', 'Psychological', 'The founder believes any economy change could break the game, so none are trusted to anyone else.', 0.71, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-305-3', (select problem_id from problems where problem_code = 'GAM-305'), 'No Way to Undo a Change', 'Operational', 'Because changes cannot be easily reversed or measured, caution is the only available safeguard.', 0.68, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-305-1', (select problem_id from problems where problem_code = 'GAM-305'), '["RC-GAM-305-1", "RC-GAM-305-2", "RC-GAM-305-3"]'::jsonb, 'Team Effectiveness', 'Gaming — Decision Rights', '[]'::jsonb, '["Write the tuning rule: what may be changed, within what range, without asking.", "Add the safeguard that makes it safe — a limit, a small share of players, an easy way back.", "Let the team tune inside it for a month and review the player numbers, not each change."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["A range plus a way back beats an approval.", "Review the numbers the changes produced, not the changes."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-305-2', (select problem_id from problems where problem_code = 'GAM-305'), '["RC-GAM-305-1", "RC-GAM-305-2", "RC-GAM-305-3"]'::jsonb, 'Team Effectiveness', 'Gaming — Decision Rights', '[]'::jsonb, '["List the five decisions you get asked about most.", "For each, write who decides and within what range.", "Put it where the team works."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["Asked five times means a missing rule."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
