insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('GAM-306', 'Hiring From the Friends and Community List', 'Team & Leadership', 'internal', 'People come from the studio''s own community and from friends of the team. Culture fit is excellent and the skill test never happens, so weak areas stay weak and nobody can say what a good hire looked like.', 5, 9, '["Hires from friends and community", "No skill test", "Cannot say why a hire worked", "Weak areas stay weak"]'::jsonb, 5, 'Hiring Repeatability', 'hiring_repeatability', '["gaming"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-306-1', (select problem_id from problems where problem_code = 'GAM-306'), 'No Written Role or Test', 'Operational', 'Hiring starts from a person being available rather than from a written job with a way to test it.', 0.75, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-306-2', (select problem_id from problems where problem_code = 'GAM-306'), 'Fit Trusted Over Skill', 'Behavioural', 'Because candidates already know the game and the team, fit is taken as evidence of ability.', 0.72, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-306-3', (select problem_id from problems where problem_code = 'GAM-306'), 'Nothing Learned Between Hires', 'Knowledge', 'What made past hires work or not is never written down, so the pattern is never seen.', 0.67, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-306-1', (select problem_id from problems where problem_code = 'GAM-306'), '["RC-GAM-306-1", "RC-GAM-306-2", "RC-GAM-306-3"]'::jsonb, 'Team Effectiveness', 'Gaming — Hiring Repeatability', '[]'::jsonb, '["Write the job first: the five things this person must do in month one.", "Set a small paid piece of real work as the test.", "Give every candidate the same piece and write down what you saw."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["Test the work, not the enthusiasm.", "The same test across people is what makes comparison possible."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-306-2', (select problem_id from problems where problem_code = 'GAM-306'), '["RC-GAM-306-1", "RC-GAM-306-2", "RC-GAM-306-3"]'::jsonb, 'Team Effectiveness', 'Gaming — Hiring Repeatability', '[]'::jsonb, '["Look at your last three hires: who worked out, and what did you see early?", "Turn that into two things you check every time.", "Look outside your community for the next role."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["A community hire is a candidate, not a shortcut."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
