insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('GAM-307', 'Meant to Be One Big Game, Building Four Small Ones', 'Strategy & Planning', 'internal', 'The founder describes a single game with a long life, and the studio keeps starting prototypes because prototypes are fun and finishing is hard. Each start is defensible and the set of them is a studio with no game.', 5, 9, '["Talks one game, starts many", "Prototypes never finished", "Direction changes each quarter", "Nothing reaches depth"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["gaming"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-307-1', (select problem_id from problems where problem_code = 'GAM-307'), 'Plan Never Checked Against the Goal', 'Strategic', 'There is no moment where what is being built is held against what the studio said it was building.', 0.77, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-307-2', (select problem_id from problems where problem_code = 'GAM-307'), 'Starting Is Easier Than Finishing', 'Psychological', 'A new prototype gives fast feedback and no risk of failure, so it is always more appealing than depth.', 0.73, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-307-3', (select problem_id from problems where problem_code = 'GAM-307'), 'Goal Too Vague to Test Against', 'Knowledge', 'The ambition is described as a kind of game rather than as things that must be true, so nothing can be judged against it.', 0.66, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-307-1', (select problem_id from problems where problem_code = 'GAM-307'), '["RC-GAM-307-1", "RC-GAM-307-2", "RC-GAM-307-3"]'::jsonb, 'Strategic Focus', 'Gaming — Plan and Vision', '[]'::jsonb, '["Write what your one game must have, in five specific things.", "Hold every active project against those five.", "Stop the ones that do not serve them and say so to the team."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["A goal you cannot test a project against is a mood.", "Say what is stopped or it continues quietly."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
