insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('GAM-308', 'The Roadmap Is Everything Anyone Ever Asked For', 'Strategy & Planning', 'internal', 'Player requests, store features, a new mode and a rendering rewrite all sit on the same list with no order. Everything is in progress, the update is late, and the one change that would keep players is buried.', 5, 9, '["Roadmap is an unranked list", "Everything in progress", "Updates late", "High-value change buried"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["gaming"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-308-1', (select problem_id from problems where problem_code = 'GAM-308'), 'Nothing Ranked', 'Strategic', 'The roadmap records requests rather than ordering them, so effort spreads across items of wildly different value.', 0.76, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-308-2', (select problem_id from problems where problem_code = 'GAM-308'), 'Player Requests Feel Like Obligations', 'Psychological', 'Refusing a vocal community request feels like betraying players, so nothing is refused.', 0.72, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-308-3', (select problem_id from problems where problem_code = 'GAM-308'), 'Loudest Request Wins', 'Behavioural', 'Whatever the community said most often this week gets built, regardless of what it is worth.', 0.67, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-308-1', (select problem_id from problems where problem_code = 'GAM-308'), '["RC-GAM-308-1", "RC-GAM-308-2", "RC-GAM-308-3"]'::jsonb, 'Strategic Focus', 'Gaming — Prioritisation', '[]'::jsonb, '["Write everything on the roadmap in one list.", "Rank it by one question: what will keep more players next month?", "Work the top two only, and tell the community what you are not doing."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["Ranking is the work; collecting requests is not.", "Telling players what you are not doing costs less than doing all of it."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-308-2', (select problem_id from problems where problem_code = 'GAM-308'), '["RC-GAM-308-1", "RC-GAM-308-2", "RC-GAM-308-3"]'::jsonb, 'Strategic Focus', 'Gaming — Prioritisation', '[]'::jsonb, '["Pick the two things you will stop this week.", "Tell the team they are stopped.", "Do not replace them until the top item ships."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["Stopping is the decision that makes the rest possible."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
