insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('GAM-309', 'Every Update Relearns What the Last One Taught', 'Strategy & Planning', 'internal', 'Which event worked, which change lost players, what the last store feature actually did — the results are in a chat thread and someone''s memory. So the studio tries the same failed thing again a year later.', 5, 9, '["Test results not recorded", "Failed changes repeated", "Event learnings in chat threads", "Knowledge leaves with people"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["gaming"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-309-1', (select problem_id from problems where problem_code = 'GAM-309'), 'Nothing Written Down', 'Operational', 'What each change and event did to the player numbers was never recorded in one place, so the studio cannot learn from itself.', 0.78, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-309-2', (select problem_id from problems where problem_code = 'GAM-309'), 'Memory Held by People', 'Knowledge', 'The studio''s knowledge lives in a few heads and in unsearchable chat history.', 0.72, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-GAM-309-3', (select problem_id from problems where problem_code = 'GAM-309'), 'Reviewing a Failure Feels Bad', 'Psychological', 'Writing up a change that lost players feels like recording a failure, so it is skipped.', 0.67, 'internal', 'Stage 0→1', '["gaming"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-309-1', (select problem_id from problems where problem_code = 'GAM-309'), '["RC-GAM-309-1", "RC-GAM-309-2", "RC-GAM-309-3"]'::jsonb, 'Strategic Focus', 'Gaming — What Gets Remembered', '[]'::jsonb, '["Start one page per change or event: what you changed, what you expected, what happened.", "Fill it in the week the numbers come back.", "Read the pages before planning the next event."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["Write the expectation down first, or the result means nothing.", "The record earns its keep only when it is read before a decision."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-GAM-309-2', (select problem_id from problems where problem_code = 'GAM-309'), '["RC-GAM-309-1", "RC-GAM-309-2", "RC-GAM-309-3"]'::jsonb, 'Strategic Focus', 'Gaming — What Gets Remembered', '[]'::jsonb, '["Write up the three biggest changes of the last year and what each did.", "Turn each into an instruction for next time.", "Read them at the start of the next planning round."]'::jsonb, '[3, 4, 5]'::jsonb, '["gaming"]'::jsonb, '["A lesson with no instruction attached is a story."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
