insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HLT-301', 'Knows the Medicine, Not How Hospitals Buy', 'Founder Psychology', 'internal', 'A clinician founder who understands the problem better than anyone. How a hospital actually approves a purchase, who signs, how long it takes and what evidence they need first are things they have never had to learn, so the sales plan is built on hope.', 5, 9, '["Strong clinically, weak on how buyers buy", "Does not know who signs", "Sales timelines badly wrong", "Pilots never convert to contracts"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["healthtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-301-1', (select problem_id from problems where problem_code = 'HLT-301'), 'Buying Process Never Learned', 'Knowledge', 'Nobody taught the founder how an institution approves spending, so each deal is a surprise.', 0.77, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-301-2', (select problem_id from problems where problem_code = 'HLT-301'), 'Clinical Work Is the Comfortable Ground', 'Psychological', 'Talking about the medicine feels productive and familiar, so the commercial learning keeps waiting.', 0.72, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-301-3', (select problem_id from problems where problem_code = 'HLT-301'), 'Enthusiasm Mistaken for a Deal', 'Behavioural', 'A doctor''s interest is read as buying intent, so the people who actually sign are never found.', 0.68, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HLT-301-1', (select problem_id from problems where problem_code = 'HLT-301'), '["RC-HLT-301-1", "RC-HLT-301-2", "RC-HLT-301-3"]'::jsonb, 'Founder Leverage', 'Healthcare & HealthTech / MedTech — Founder Skill Fit', '[]'::jsonb, '["Take your most promising pilot and write down every person who must say yes before money moves.", "Mark which of them you have actually met.", "Meet the one who signs, before you do any more clinical demos."]'::jsonb, '[3, 4, 5]'::jsonb, '["healthtech"]'::jsonb, '["A clinician''s enthusiasm is not a purchase order.", "Find the signature before building the pilot."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
