insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HLT-302', 'The Founder Still Sees Patients and Runs the Company', 'Founder Psychology', 'internal', 'Clinical hours, product decisions, funding conversations and the regulatory file all sit with the same person. Whatever has a patient or a deadline attached wins, and the company work happens at night.', 5, 9, '["Clinical work and company work compete", "Regulatory file slips", "Company work done at night", "Nothing has protected time"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["healthtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-302-1', (select problem_id from problems where problem_code = 'HLT-302'), 'Urgent Beats Important', 'Behavioural', 'Clinical duties carry a person on the other end, so they always win over work with a longer horizon.', 0.76, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-302-2', (select problem_id from problems where problem_code = 'HLT-302'), 'No Hours Reserved', 'Operational', 'No hours are protected for the regulatory or commercial work, so it happens only when everything else is done.', 0.72, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-302-3', (select problem_id from problems where problem_code = 'HLT-302'), 'Clinical Identity Holds On', 'Psychological', 'Seeing patients is who the founder is, so reducing it feels like a loss rather than a decision.', 0.68, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HLT-302-1', (select problem_id from problems where problem_code = 'HLT-302'), '["RC-HLT-302-1", "RC-HLT-302-2", "RC-HLT-302-3"]'::jsonb, 'Founder Leverage', 'Healthcare & HealthTech / MedTech — Founder Time Use', '[]'::jsonb, '["Write down where your hours went last week, split clinical and company.", "Decide the split you actually need for the next quarter and write it down.", "Protect the company hours in the calendar as firmly as a clinic."]'::jsonb, '[3, 4, 5]'::jsonb, '["healthtech"]'::jsonb, '["An unprotected hour goes to whoever is shouting.", "Decide the split deliberately rather than discovering it each week."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HLT-302-2', (select problem_id from problems where problem_code = 'HLT-302'), '["RC-HLT-302-1", "RC-HLT-302-2", "RC-HLT-302-3"]'::jsonb, 'Founder Leverage', 'Healthcare & HealthTech / MedTech — Founder Time Use', '[]'::jsonb, '["List the company tasks only you can do.", "Give one of the others to someone else with the steps written down.", "Do not take it back for a month."]'::jsonb, '[3, 4, 5]'::jsonb, '["healthtech"]'::jsonb, '["Write the steps before handing over, or it returns."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
