insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HLT-303', 'Only the Founder Can Explain It to a Clinician', 'Founder Psychology', 'internal', 'Every important conversation with a doctor, a hospital or a regulator needs the founder in the room, because the clinical reasoning was never written down in a form anyone else could carry.', 5, 9, '["Founder in every clinical conversation", "Clinical reasoning unwritten", "Sales cannot run without the founder", "Growth limited by one diary"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["healthtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-303-1', (select problem_id from problems where problem_code = 'HLT-303'), 'Clinical Reasoning Never Written', 'Knowledge', 'The argument that convinces a clinician lives in the founder''s head and was never written as material.', 0.78, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-303-2', (select problem_id from problems where problem_code = 'HLT-303'), 'Nobody Else Trusted With It', 'Psychological', 'The founder fears a non-clinician saying something wrong, so no one is allowed to try.', 0.72, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-303-3', (select problem_id from problems where problem_code = 'HLT-303'), 'No Training Material Exists', 'Operational', 'There is nothing a new person could learn the clinical case from, so the dependency has no way out.', 0.68, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HLT-303-1', (select problem_id from problems where problem_code = 'HLT-303'), '["RC-HLT-303-1", "RC-HLT-303-2", "RC-HLT-303-3"]'::jsonb, 'Founder Leverage', 'Healthcare & HealthTech / MedTech — Founder Dependency', '[]'::jsonb, '["Write down the clinical argument as you actually make it, including the three objections you always get.", "Have one non-clinical person deliver it to a friendly doctor while you listen and say nothing.", "Fix what the material got wrong, not what the person got wrong."]'::jsonb, '[3, 4, 5]'::jsonb, '["healthtech"]'::jsonb, '["If they cannot deliver it from the page, the page is wrong.", "Listening without interrupting is the only honest test."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HLT-303-2', (select problem_id from problems where problem_code = 'HLT-303'), '["RC-HLT-303-1", "RC-HLT-303-2", "RC-HLT-303-3"]'::jsonb, 'Founder Leverage', 'Healthcare & HealthTech / MedTech — Founder Dependency', '[]'::jsonb, '["Record your next three clinical conversations, with consent.", "Write down the questions that came up and your answers.", "Turn that into the material a new person learns from."]'::jsonb, '[3, 4, 5]'::jsonb, '["healthtech"]'::jsonb, '["The material writes itself if you record what actually gets asked."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
