insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HLT-304', 'Clinical, Product and Compliance All Blur Together', 'Team & Leadership', 'internal', 'The clinical advisor comments on product, the engineer decides what counts as a clinical claim, and nobody owns compliance until an auditor asks. Each of these has a real owner on paper and not in practice.', 5, 9, '["Clinical and product decisions blur", "Compliance owned by nobody", "Claims decided by whoever writes the copy", "Ownership unclear under audit"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["healthtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-304-1', (select problem_id from problems where problem_code = 'HLT-304'), 'Roles Never Set', 'Behavioural', 'The team formed around people rather than jobs, so the boundary between clinical, product and compliance was never drawn.', 0.77, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-304-2', (select problem_id from problems where problem_code = 'HLT-304'), 'Overlap Feels Collaborative', 'Psychological', 'Everyone contributing everywhere feels like a good team, which hides that regulated responsibilities have no owner.', 0.70, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-304-3', (select problem_id from problems where problem_code = 'HLT-304'), 'Handovers Unwritten', 'Operational', 'What must be signed off before a claim or a release goes out was never agreed in writing.', 0.69, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HLT-304-1', (select problem_id from problems where problem_code = 'HLT-304'), '["RC-HLT-304-1", "RC-HLT-304-2", "RC-HLT-304-3"]'::jsonb, 'Team Effectiveness', 'Healthcare & HealthTech / MedTech — Role Clarity', '[]'::jsonb, '["Write down which decisions are clinical, which are product and which are compliance.", "Put one name against each group.", "Write what must be signed off before anything goes to a patient or a buyer."]'::jsonb, '[3, 4, 5]'::jsonb, '["healthtech"]'::jsonb, '["In a regulated business, an unowned decision is a finding waiting to happen.", "The sign-off list is the handover."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HLT-304-2', (select problem_id from problems where problem_code = 'HLT-304'), '["RC-HLT-304-1", "RC-HLT-304-2", "RC-HLT-304-3"]'::jsonb, 'Team Effectiveness', 'Healthcare & HealthTech / MedTech — Role Clarity', '[]'::jsonb, '["Pick the decision type that caused the most confusion last quarter.", "Give it one owner and tell the team.", "Review that one alone next quarter."]'::jsonb, '[3, 4, 5]'::jsonb, '["healthtech"]'::jsonb, '["One boundary drawn properly beats a whole new structure."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
