insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HLT-305', 'Every Clinical Judgement Call Reaches the Founder', 'Team & Leadership', 'internal', 'Whether a case is in scope, whether a claim is fair, whether an edge case is safe — all of it comes to the founder, because none of it has ever been written as a rule. So the work waits and the founder becomes the process.', 5, 9, '["All clinical judgement calls escalate", "No written scope rules", "Work waits on the founder", "Team stops deciding anything"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["healthtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-305-1', (select problem_id from problems where problem_code = 'HLT-305'), 'Rules Never Written', 'Knowledge', 'The founder''s clinical judgement was never turned into criteria, so every case needs them personally.', 0.78, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-305-2', (select problem_id from problems where problem_code = 'HLT-305'), 'Safety Used to Justify the Bottleneck', 'Psychological', 'Because the stakes are clinical, centralising every call feels responsible rather than slow.', 0.72, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-305-3', (select problem_id from problems where problem_code = 'HLT-305'), 'No Safe Way to Delegate', 'Operational', 'There is no written line between what may be decided and what must escalate, so everything escalates.', 0.68, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HLT-305-1', (select problem_id from problems where problem_code = 'HLT-305'), '["RC-HLT-305-1", "RC-HLT-305-2", "RC-HLT-305-3"]'::jsonb, 'Team Effectiveness', 'Healthcare & HealthTech / MedTech — Decision Rights', '[]'::jsonb, '["Write the criteria for what is clearly in scope and what is clearly not.", "Write the short list of things that must always come to you.", "Let the team work the clear cases for a month and review the escalations, not every case."]'::jsonb, '[3, 4, 5]'::jsonb, '["healthtech"]'::jsonb, '["Write the escalation line so the team knows both sides of it.", "In a clinical business the rule is the safeguard, not the approval."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HLT-305-2', (select problem_id from problems where problem_code = 'HLT-305'), '["RC-HLT-305-1", "RC-HLT-305-2", "RC-HLT-305-3"]'::jsonb, 'Team Effectiveness', 'Healthcare & HealthTech / MedTech — Decision Rights', '[]'::jsonb, '["List the ten cases you were asked about last month.", "Mark which were genuinely borderline.", "Turn the clear ones into written criteria this week."]'::jsonb, '[3, 4, 5]'::jsonb, '["healthtech"]'::jsonb, '["If most escalations were not borderline, the rule was missing."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
