insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HLT-306', 'Hiring Clinicians From the Founder''s Own Network', 'Team & Leadership', 'internal', 'Every hire comes from someone the founder trained or worked with. It is fast and safe and it means the company has one point of view, no commercial or regulatory depth, and no written idea of what any role requires.', 5, 9, '["Hires all from one network", "No written role", "One point of view across the team", "Commercial and regulatory depth missing"]'::jsonb, 5, 'Hiring Repeatability', 'hiring_repeatability', '["healthtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-306-1', (select problem_id from problems where problem_code = 'HLT-306'), 'No Written Role', 'Operational', 'Hiring starts from a trusted person being available rather than from a written job.', 0.76, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-306-2', (select problem_id from problems where problem_code = 'HLT-306'), 'Trust Substituted for Assessment', 'Behavioural', 'Because the founder already knows the candidate, no test of the actual work happens.', 0.72, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-306-3', (select problem_id from problems where problem_code = 'HLT-306'), 'Same Network, Same Blind Spots', 'Strategic', 'Hiring from one professional circle reproduces its gaps, so the missing skills stay missing.', 0.69, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HLT-306-1', (select problem_id from problems where problem_code = 'HLT-306'), '["RC-HLT-306-1", "RC-HLT-306-2", "RC-HLT-306-3"]'::jsonb, 'Team Effectiveness', 'Healthcare & HealthTech / MedTech — Hiring Repeatability', '[]'::jsonb, '["Write the job before you look: the five things this person must do in month one.", "Write how you will test each one.", "Interview at least two people from outside your network for it."]'::jsonb, '[3, 4, 5]'::jsonb, '["healthtech"]'::jsonb, '["Test the work, not the relationship.", "One outside candidate is what tells you what your network was missing."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HLT-306-2', (select problem_id from problems where problem_code = 'HLT-306'), '["RC-HLT-306-1", "RC-HLT-306-2", "RC-HLT-306-3"]'::jsonb, 'Team Effectiveness', 'Healthcare & HealthTech / MedTech — Hiring Repeatability', '[]'::jsonb, '["List the skills your team does not have.", "Rank them by what is blocking you now.", "Hire the top one from outside your circle, with a written role."]'::jsonb, '[3, 4, 5]'::jsonb, '["healthtech"]'::jsonb, '["Hire for the gap, not from the network."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
