insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HLT-307', 'Aiming at Hospitals, Building for Individual Doctors', 'Strategy & Planning', 'internal', 'The company describes itself as institutional, and every feature so far serves one clinician working alone. Each feature was asked for by a real user, and together they are a product no hospital can buy.', 5, 9, '["Says institutional, builds for individuals", "Features requested by single users", "No institution-level capability", "Pilots stay single-site"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["healthtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-307-1', (select problem_id from problems where problem_code = 'HLT-307'), 'Plan Never Checked Against the Goal', 'Strategic', 'Nobody holds the roadmap against the stated buyer, so the product drifts toward whoever asks loudest.', 0.77, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-307-2', (select problem_id from problems where problem_code = 'HLT-307'), 'Individual Users Are Easier to Please', 'Behavioural', 'One clinician gives fast, warm feedback; an institution gives slow, hard requirements, so the easy feedback wins.', 0.72, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-307-3', (select problem_id from problems where problem_code = 'HLT-307'), 'Buyer Never Described Properly', 'Knowledge', 'The target buyer is named as a type of organisation rather than described as requirements, so nothing can be tested against it.', 0.67, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
