insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HLT-308', 'The Regulatory File, Three Pilots and a Rebuild, Together', 'Strategy & Planning', 'internal', 'The approval submission, several pilot sites and a technical rebuild are all live at once. The submission is the one with a hard gate in front of the whole company, and it is getting the same attention as the rest.', 5, 9, '["Regulatory work runs alongside everything", "Several pilots at once", "Rebuild competing for the same people", "The hard gate not prioritised"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["healthtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-308-1', (select problem_id from problems where problem_code = 'HLT-308'), 'Nothing Ranked', 'Strategic', 'Work is listed rather than ordered, so a blocking submission gets the same resources as a nice-to-have.', 0.78, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-308-2', (select problem_id from problems where problem_code = 'HLT-308'), 'Every Pilot Feels Unmissable', 'Psychological', 'Each interested site feels like a chance that will not come again, so none are declined or delayed.', 0.72, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-308-3', (select problem_id from problems where problem_code = 'HLT-308'), 'Blocking Work Not Identified', 'Knowledge', 'Nobody has written down which single piece of work gates everything else, so it is not treated differently.', 0.68, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HLT-308-1', (select problem_id from problems where problem_code = 'HLT-308'), '["RC-HLT-308-1", "RC-HLT-308-2", "RC-HLT-308-3"]'::jsonb, 'Strategic Focus', 'Healthcare & HealthTech / MedTech — Prioritisation', '[]'::jsonb, '["Write down which single piece of work, if late, delays everything else.", "Give it the best people and protect them from the rest.", "Delay or decline whatever competes with it, and say so out loud."]'::jsonb, '[3, 4, 5]'::jsonb, '["healthtech"]'::jsonb, '["One gate first; everything behind it is waiting anyway.", "Declining a pilot politely costs less than missing the submission."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HLT-308-2', (select problem_id from problems where problem_code = 'HLT-308'), '["RC-HLT-308-1", "RC-HLT-308-2", "RC-HLT-308-3"]'::jsonb, 'Strategic Focus', 'Healthcare & HealthTech / MedTech — Prioritisation', '[]'::jsonb, '["List everything running now and what each needs from your scarcest person.", "Rank by what unblocks the most.", "Pause the bottom two this week."]'::jsonb, '[3, 4, 5]'::jsonb, '["healthtech"]'::jsonb, '["Rank by what unblocks, not by what excites."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
