insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('HLT-309', 'The Regulatory and Pilot History Lives in Email', 'Strategy & Planning', 'internal', 'What the regulator asked last time, why a pilot site pulled out, which claim was rejected and why — all of it is in mailboxes and in the founder''s memory. In a regulated business that is both a slowdown and a risk.', 5, 9, '["Regulator correspondence only in email", "Pilot failures not written up", "Same questions answered again", "Audit trail depends on memory"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["healthtech"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-309-1', (select problem_id from problems where problem_code = 'HLT-309'), 'Nothing Written Down', 'Operational', 'Decisions, rejections and their reasons were never recorded in one place, so the company cannot learn or evidence its own history.', 0.79, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-309-2', (select problem_id from problems where problem_code = 'HLT-309'), 'Memory Held by People', 'Knowledge', 'The regulatory and commercial history lives in a few heads and a few mailboxes.', 0.73, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-HLT-309-3', (select problem_id from problems where problem_code = 'HLT-309'), 'Writing Up a Rejection Feels Like Recording Failure', 'Psychological', 'Documenting why something was refused feels like creating evidence against yourself, so it is avoided.', 0.67, 'internal', 'Stage 0→1', '["healthtech"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HLT-309-1', (select problem_id from problems where problem_code = 'HLT-309'), '["RC-HLT-309-1", "RC-HLT-309-2", "RC-HLT-309-3"]'::jsonb, 'Strategic Focus', 'Healthcare & HealthTech / MedTech — What Gets Remembered', '[]'::jsonb, '["Start one page per regulatory interaction and per pilot: what was asked, what you answered, what happened.", "Fill it in the week it happens.", "Read the pages before the next submission or pilot."]'::jsonb, '[3, 4, 5]'::jsonb, '["healthtech"]'::jsonb, '["In a regulated business the record is part of the product.", "Write it when it happens or it will not be written."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-HLT-309-2', (select problem_id from problems where problem_code = 'HLT-309'), '["RC-HLT-309-1", "RC-HLT-309-2", "RC-HLT-309-3"]'::jsonb, 'Strategic Focus', 'Healthcare & HealthTech / MedTech — What Gets Remembered', '[]'::jsonb, '["Write up why each pilot that ended, ended.", "Turn each into an instruction for the next one.", "Read them before signing the next pilot."]'::jsonb, '[3, 4, 5]'::jsonb, '["healthtech"]'::jsonb, '["A lesson with no instruction attached is a story."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
