insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRV-301', 'Guests Love the Place, the Founder Cannot Read the Season', 'Founder Psychology', 'internal', 'The founder is genuinely good at hosting and the reviews say so. Deciding what to charge in which week, how much to hold back for late bookings, and what a booking costs once commission is paid, has never been learned.', 5, 9, '["Great hosting, weak pricing", "Same rate all year", "Commission cost not counted", "Cannot say which channel pays best"]'::jsonb, 1, 'Founder Skill Fit', 'skill_stage_fit', '["travel_hospitality"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-301-1', (select problem_id from problems where problem_code = 'TRV-301'), 'Pricing Never Learned', 'Knowledge', 'Nobody taught the founder how demand moves through a year or how to price against it, so one rate is used for everything.', 0.77, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-301-2', (select problem_id from problems where problem_code = 'TRV-301'), 'Hosting Is the Comfortable Work', 'Psychological', 'Looking after guests feels like the real job, so the pricing and channel work is always postponed.', 0.72, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-301-3', (select problem_id from problems where problem_code = 'TRV-301'), 'Commission Treated as Unavoidable', 'Behavioural', 'Platform commission is accepted as a cost of doing business rather than measured per channel.', 0.67, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-301-1', (select problem_id from problems where problem_code = 'TRV-301'), '["RC-TRV-301-1", "RC-TRV-301-2", "RC-TRV-301-3"]'::jsonb, 'Founder Leverage', 'Hospitality, Travel & Tourism — Founder Skill Fit', '[]'::jsonb, '["Work out what one booking actually leaves you after commission, cleaning and consumables.", "Do it separately for each channel you take bookings from.", "Make your next pricing or channel decision from those numbers."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["The rate is not the revenue; what is left after commission is.", "One number per channel beats a booking total you cannot act on."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-301-2', (select problem_id from problems where problem_code = 'TRV-301'), '["RC-TRV-301-1", "RC-TRV-301-2", "RC-TRV-301-3"]'::jsonb, 'Founder Leverage', 'Hospitality, Travel & Tourism — Founder Skill Fit', '[]'::jsonb, '["Write down your last twelve months of occupancy by month.", "Mark your three busiest and three quietest weeks.", "Set a different rate for each group before the next season."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["A single rate all year gives away money in the busy weeks and empty rooms in the quiet ones."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into questions (question_code, category, question_text, problem_id, root_cause_id, question_type, difficulty_level, priority, is_distress_tagged, red_flag_pattern, green_flag_pattern, primary_stage_group, industry_relevance) values ('S0-TRV-301-1', 'Founder Psychology', 'Do you know what one booking leaves you after commission?', (select problem_id from problems where problem_code = 'TRV-301'), (select root_cause_id from root_causes where root_cause_code = 'RC-TRV-301-1'), 'open_text', 2, 'CORE', false, 'No', 'Yes, worked out', 'Stage 0', '["travel_hospitality"]'::jsonb) on conflict (question_code) do nothing;
