insert into question_industry_mapping (question_id, industry_code, stage_group, applicability_type) values ((select question_id from questions where question_code = 'S10-TRV-301-2'), 'travel_hospitality', 'Stage 1→10+', 'primary') on conflict (question_id, industry_code, stage_group) do nothing;
insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRV-302', 'The Founder Is the Front Desk', 'Founder Psychology', 'internal', 'Guest messages, a broken geyser, a late check-in, a bad review to answer. The founder is on call every day and the work that would stop these happening — training, checklists, a maintenance schedule — never begins.', 5, 9, '["Founder answers all guest messages", "On call every day", "No time for systems", "The same guest problems repeat"]'::jsonb, 1, 'Founder Time Use', 'time_allocation_reality', '["travel_hospitality"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-302-1', (select problem_id from problems where problem_code = 'TRV-302'), 'Handling Instead of Preventing', 'Behavioural', 'Each guest problem is solved personally and the reason it keeps happening is never worked on.', 0.76, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-302-2', (select problem_id from problems where problem_code = 'TRV-302'), 'No Hours Reserved', 'Operational', 'No hours are protected for training or maintenance planning, so only today''s guest gets attention.', 0.72, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-302-3', (select problem_id from problems where problem_code = 'TRV-302'), 'Being Available Feels Like Hospitality', 'Psychological', 'The founder believes personal availability is the service, which makes stepping back feel like lowering standards.', 0.68, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-302-1', (select problem_id from problems where problem_code = 'TRV-302'), '["RC-TRV-302-1", "RC-TRV-302-2", "RC-TRV-302-3"]'::jsonb, 'Founder Leverage', 'Hospitality, Travel & Tourism — Founder Time Use', '[]'::jsonb, '["Write down every guest problem for one month and group them.", "Take the biggest group and fix its cause — a checklist, a service schedule, a trained person.", "Count that group again next month."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["A repeat complaint is a process gap, not bad luck.", "Count it before and after or you will not know it worked."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-302-2', (select problem_id from problems where problem_code = 'TRV-302'), '["RC-TRV-302-1", "RC-TRV-302-2", "RC-TRV-302-3"]'::jsonb, 'Founder Leverage', 'Hospitality, Travel & Tourism — Founder Time Use', '[]'::jsonb, '["Write down where your hours went last week.", "Mark the ones only you could have done.", "Train one person to handle guest messages with written answers for the common ones."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["Written answers for common questions free more hours than working faster."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into questions (question_code, category, question_text, problem_id, root_cause_id, question_type, difficulty_level, priority, is_distress_tagged, red_flag_pattern, green_flag_pattern, primary_stage_group, industry_relevance) values ('S0-TRV-302-1', 'Founder Psychology', 'Who answers guest messages?', (select problem_id from problems where problem_code = 'TRV-302'), (select root_cause_id from root_causes where root_cause_code = 'RC-TRV-302-1'), 'open_text', 2, 'CORE', false, 'The founder, always', 'A trained person with written answers', 'Stage 0', '["travel_hospitality"]'::jsonb) on conflict (question_code) do nothing;
