insert into question_industry_mapping (question_id, industry_code, stage_group, applicability_type) values ((select question_id from questions where question_code = 'S10-TRV-302-2'), 'travel_hospitality', 'Stage 1→10+', 'primary') on conflict (question_id, industry_code, stage_group) do nothing;
insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRV-303', 'The Experience Is the Founder', 'Founder Psychology', 'internal', 'Guests come for the founder''s welcome, their recommendations, their way of doing things. None of it is written down, so the experience cannot be repeated by staff and the business cannot grow past one person''s presence.', 5, 9, '["Experience depends on the founder being there", "Nothing written about service standards", "Reviews mention the founder personally", "Cannot open a second property"]'::jsonb, 1, 'Founder Dependency', 'founder_dependency', '["travel_hospitality"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-303-1', (select problem_id from problems where problem_code = 'TRV-303'), 'Service Never Written Down', 'Knowledge', 'What makes the welcome good was never turned into steps anyone could follow, so it leaves when the founder does.', 0.78, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-303-2', (select problem_id from problems where problem_code = 'TRV-303'), 'Presence Treated as the Product', 'Psychological', 'Because guests praise the founder personally, writing the service down feels like replacing the thing they came for.', 0.73, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-303-3', (select problem_id from problems where problem_code = 'TRV-303'), 'No Training Material', 'Operational', 'There is nothing a new staff member could learn the standard from, so the dependency has no exit.', 0.67, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-303-1', (select problem_id from problems where problem_code = 'TRV-303'), '["RC-TRV-303-1", "RC-TRV-303-2", "RC-TRV-303-3"]'::jsonb, 'Founder Leverage', 'Hospitality, Travel & Tourism — Founder Dependency', '[]'::jsonb, '["Write your welcome as steps: what is said, what is offered, what is checked.", "Have one staff member do it while you watch and say nothing.", "Fix what the steps got wrong, not what the person got wrong."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["If they cannot do it from the steps, the steps are wrong.", "Watching without stepping in is the only honest test."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-303-2', (select problem_id from problems where problem_code = 'TRV-303'), '["RC-TRV-303-1", "RC-TRV-303-2", "RC-TRV-303-3"]'::jsonb, 'Founder Leverage', 'Hospitality, Travel & Tourism — Founder Dependency', '[]'::jsonb, '["Write your ten best local recommendations with why each suits which guest.", "Put it where staff can use it.", "Ask departing guests whether they got a good recommendation."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["What is in your head serves the guests in front of you; what is written serves all of them."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
