insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRV-304', 'Whoever Is On Shift Does Whatever Comes Up', 'Team & Leadership', 'internal', 'Housekeeping, check-in, maintenance calls and the booking platform all land on whoever is present. It works on a quiet day and falls apart on a full one, and nobody can be held to a standard they were never given.', 5, 9, '["Jobs follow the shift, not the person", "No owner for housekeeping standards", "Platform listings updated by anyone", "Standards drop when busy"]'::jsonb, 5, 'Role Clarity', 'team_structure_role_clarity', '["travel_hospitality"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-304-1', (select problem_id from problems where problem_code = 'TRV-304'), 'Roles Never Set', 'Behavioural', 'Staff were hired as cover rather than for defined jobs, so no task has a permanent owner or standard.', 0.76, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-304-2', (select problem_id from problems where problem_code = 'TRV-304'), 'Everyone Does Everything', 'Psychological', 'Flexible staff feel like a strength on a quiet day, which hides that nothing is owned on a busy one.', 0.70, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-304-3', (select problem_id from problems where problem_code = 'TRV-304'), 'Handovers Unwritten', 'Operational', 'What must be true at the end of a shift for the next one to start clean was never agreed.', 0.68, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-304-1', (select problem_id from problems where problem_code = 'TRV-304'), '["RC-TRV-304-1", "RC-TRV-304-2", "RC-TRV-304-3"]'::jsonb, 'Team Effectiveness', 'Hospitality, Travel & Tourism — Role Clarity', '[]'::jsonb, '["List the jobs that must happen every day whoever is on.", "Put one name against each, with the standard written next to it.", "Write the shift handover checklist and put it where the shift changes."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["Own the job with its standard, not just the shift.", "Most misses happen at the handover."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-304-2', (select problem_id from problems where problem_code = 'TRV-304'), '["RC-TRV-304-1", "RC-TRV-304-2", "RC-TRV-304-3"]'::jsonb, 'Team Effectiveness', 'Hospitality, Travel & Tourism — Role Clarity', '[]'::jsonb, '["Pick the job guests notice most when it slips.", "Give it one owner and one written standard.", "Check that one job daily for two weeks."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["One owner with a written standard beats a new rota."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
