insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRV-305', 'No One Can Discount, Refund or Upgrade Without Asking', 'Team & Leadership', 'internal', 'A guest complains at eleven at night and the person on duty cannot offer anything. So the guest waits, the review gets written, and the founder''s phone is the only route to a decision worth a few hundred rupees.', 5, 9, '["All refunds need the founder", "Staff cannot offer an upgrade", "Complaints wait for a phone call", "Bad reviews from slow resolution"]'::jsonb, 5, 'Decision Rights', 'decision_rights', '["travel_hospitality"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-305-1', (select problem_id from problems where problem_code = 'TRV-305'), 'Limits Never Written', 'Operational', 'No amount has been written down that staff may offer to resolve a complaint, so nothing can be offered.', 0.78, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-305-2', (select problem_id from problems where problem_code = 'TRV-305'), 'Judgement Not Trusted Yet', 'Psychological', 'The founder has never seen staff make these calls, so does not trust them to — and cannot while nobody is allowed.', 0.72, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-305-3', (select problem_id from problems where problem_code = 'TRV-305'), 'Cost of Waiting Not Counted', 'Knowledge', 'The price of a bad review caused by a slow answer has never been compared to the cost of the discount.', 0.67, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-305-1', (select problem_id from problems where problem_code = 'TRV-305'), '["RC-TRV-305-1", "RC-TRV-305-2", "RC-TRV-305-3"]'::jsonb, 'Team Effectiveness', 'Hospitality, Travel & Tourism — Decision Rights', '[]'::jsonb, '["Write the service recovery rule: what staff may offer, up to what value, without asking.", "Train them on it with three real examples.", "Review the monthly total spent and what it saved, not each case."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["A guest problem solved in ten minutes costs less than a review.", "Review the total, not each decision."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-305-2', (select problem_id from problems where problem_code = 'TRV-305'), '["RC-TRV-305-1", "RC-TRV-305-2", "RC-TRV-305-3"]'::jsonb, 'Team Effectiveness', 'Hospitality, Travel & Tourism — Decision Rights', '[]'::jsonb, '["List the five things staff call you about most at night.", "For each, write what they may do alone.", "Put it where the night shift will see it."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["Five calls a week is a missing rule, not a busy phone."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
