insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRV-306', 'Hiring Before the Season, From Whoever Is Around', 'Team & Leadership', 'internal', 'Staff are taken on in a rush before the season, from whoever is locally available, with nothing written about the job. Many leave at the end of it and the same rush happens next year.', 5, 9, '["Hiring rushed before a season", "No written job description", "Most staff leave after the season", "Same rush every year"]'::jsonb, 5, 'Hiring Repeatability', 'hiring_repeatability', '["travel_hospitality"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-306-1', (select problem_id from problems where problem_code = 'TRV-306'), 'No Written Role', 'Operational', 'Hiring starts from the season approaching rather than from a written job, so anyone available looks suitable.', 0.76, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-306-2', (select problem_id from problems where problem_code = 'TRV-306'), 'Seasonality Used as an Excuse', 'Behavioural', 'Because turnover is expected, no effort goes into why people leave or who stays.', 0.72, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-306-3', (select problem_id from problems where problem_code = 'TRV-306'), 'Nothing Learned Between Seasons', 'Knowledge', 'Who was good and why is never written down, so each season starts from nothing.', 0.68, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
