insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-306-2', (select problem_id from problems where problem_code = 'TRV-306'), '["RC-TRV-306-1", "RC-TRV-306-2", "RC-TRV-306-3"]'::jsonb, 'Team Effectiveness', 'Hospitality, Travel & Tourism — Hiring Repeatability', '[]'::jsonb, '["Write down who stayed last season and why.", "Offer those people something to come back to before the season starts.", "Start hiring two months earlier than you did last year."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["A returning staff member is cheaper than a new one, twice over."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
