insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRV-307', 'Talks About a Small Chain, Runs a Personal Guesthouse', 'Strategy & Planning', 'internal', 'The founder describes several properties in a few years, and everything about how this one works depends on them: the welcome, the suppliers, the pricing, the standards. Nothing being built could be copied.', 5, 9, '["Talks chain, runs a one-off", "Nothing written to copy", "Standards live with the founder", "Suppliers chosen locally and personally"]'::jsonb, 6, 'Plan and Vision', 'plan_to_vision_alignment', '["travel_hospitality"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-307-1', (select problem_id from problems where problem_code = 'TRV-307'), 'Plan Never Checked Against the Goal', 'Strategic', 'Nobody asks whether today''s way of working could be repeated elsewhere, so the gap grows quietly.', 0.77, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-307-2', (select problem_id from problems where problem_code = 'TRV-307'), 'Today''s Guest Decides Everything', 'Behavioural', 'Every choice is made for the guest in front of the founder, and none of them asks whether it would copy.', 0.72, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-307-3', (select problem_id from problems where problem_code = 'TRV-307'), 'Goal Is a Number, Not a Description', 'Knowledge', 'The ambition is a count of properties rather than a list of what must be true to open one.', 0.67, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-307-1', (select problem_id from problems where problem_code = 'TRV-307'), '["RC-TRV-307-1", "RC-TRV-307-2", "RC-TRV-307-3"]'::jsonb, 'Strategic Focus', 'Hospitality, Travel & Tourism — Plan and Vision', '[]'::jsonb, '["Write what must exist before you could open a second property: standards, training, pricing, suppliers.", "Mark which exist today.", "Build the missing one that would take longest, starting now."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["A second property needs written things, not more effort.", "Start with the slowest missing piece."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-307-2', (select problem_id from problems where problem_code = 'TRV-307'), '["RC-TRV-307-1", "RC-TRV-307-2", "RC-TRV-307-3"]'::jsonb, 'Strategic Focus', 'Hospitality, Travel & Tourism — Plan and Vision', '[]'::jsonb, '["Take one decision you made this month and ask whether it works at three properties.", "If not, write what you would do instead.", "Do that instead, this month."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["Test the ambition against one real decision, not the whole plan."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
