insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRV-308', 'A Renovation, a New Channel and an Experiences Menu, All Before Season', 'Strategy & Planning', 'internal', 'Three things are half-done and the season starts in six weeks. Each was a good idea in a quiet month, and together they mean the season opens with a building site and a half-listed property.', 5, 9, '["Several projects before a season", "All half-finished", "No ranking", "Season opens with things incomplete"]'::jsonb, 6, 'Prioritisation', 'prioritization_discipline', '["travel_hospitality"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-308-1', (select problem_id from problems where problem_code = 'TRV-308'), 'Nothing Ranked', 'Strategic', 'Ideas go on a list and are never ordered, so effort spreads across things of unequal value against a hard deadline.', 0.77, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-308-2', (select problem_id from problems where problem_code = 'TRV-308'), 'Quiet Months Invite Too Many Starts', 'Behavioural', 'The off-season feels like free time, so more is started than can be finished before the season.', 0.72, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-308-3', (select problem_id from problems where problem_code = 'TRV-308'), 'Deadline Not Treated as Real', 'Psychological', 'The season''s start is known but not planned backwards from, so everything feels like it still has time.', 0.68, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-308-1', (select problem_id from problems where problem_code = 'TRV-308'), '["RC-TRV-308-1", "RC-TRV-308-2", "RC-TRV-308-3"]'::jsonb, 'Strategic Focus', 'Hospitality, Travel & Tourism — Prioritisation', '[]'::jsonb, '["Write the date the season starts and count backwards.", "Pick the one thing that must be finished by then and say it out loud.", "Stop or postpone the others this week and tell everyone."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["Plan backwards from the date, not forwards from today.", "Say what is postponed or it continues quietly."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-308-2', (select problem_id from problems where problem_code = 'TRV-308'), '["RC-TRV-308-1", "RC-TRV-308-2", "RC-TRV-308-3"]'::jsonb, 'Strategic Focus', 'Hospitality, Travel & Tourism — Prioritisation', '[]'::jsonb, '["List everything in progress and what each still needs.", "Rank by what a guest will notice in week one of the season.", "Finish the top one before touching the others."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["Finish what the guest sees first."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
