insert into problems (problem_code, problem_name, category, layer, description, severity_min, severity_max, symptoms, pillar_id, subcategory, dimension_code, industry_relevance) values ('TRV-309', 'Every Season Starts With the Same Surprises', 'Strategy & Planning', 'internal', 'Which weeks actually filled, which supplier let you down in the rains, what guests complained about last year — it is all in memory and in a booking platform nobody exports. So each season repeats mistakes it already paid for.', 5, 9, '["Occupancy history not recorded", "Supplier problems repeat each season", "Complaint patterns not tracked", "Knowledge leaves with seasonal staff"]'::jsonb, 6, 'What Gets Remembered', 'institutional_memory', '["travel_hospitality"]'::jsonb) on conflict (problem_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-309-1', (select problem_id from problems where problem_code = 'TRV-309'), 'Nothing Written Down', 'Operational', 'Occupancy, supplier performance and complaint patterns were never recorded in one place, so the business relearns them yearly.', 0.79, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-309-2', (select problem_id from problems where problem_code = 'TRV-309'), 'Memory Held by People', 'Knowledge', 'What the property knows lives in the founder''s head and in staff who leave at the end of each season.', 0.73, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into root_causes (root_cause_code, problem_id, root_cause_name, root_cause_category, explanation, confidence_weight, layer, primary_stage_group, industry_relevance) values ('RC-TRV-309-3', (select problem_id from problems where problem_code = 'TRV-309'), 'Looking Back Feels Like Blame', 'Psychological', 'Reviewing a bad season honestly feels like finding fault, so it is skipped and the lesson is lost.', 0.67, 'internal', 'Stage 0→1', '["travel_hospitality"]'::jsonb) on conflict (root_cause_code) do nothing;
insert into interventions (intervention_code, problem_id, root_cause_ids, capability_domain, section, recommended_frameworks, immediate_next_steps, stage_relevance, industry_relevance, design_principles, secondary_root_cause_ids) values ('INT-TRV-309-1', (select problem_id from problems where problem_code = 'TRV-309'), '["RC-TRV-309-1", "RC-TRV-309-2", "RC-TRV-309-3"]'::jsonb, 'Strategic Focus', 'Hospitality, Travel & Tourism — What Gets Remembered', '[]'::jsonb, '["Write down last year''s occupancy week by week, and your three worst complaints.", "Add one page per supplier: what went wrong and when.", "Read all of it before you plan or price the next season."]'::jsonb, '[3, 4, 5]'::jsonb, '["travel_hospitality"]'::jsonb, '["A season you did not write down cannot teach you anything.", "The record is worth nothing unless it is read before a decision."]'::jsonb, '[]'::jsonb) on conflict (intervention_code) do nothing;
